// Lesson 1: follow one request through a full stack app, using only Node.js (no libraries).
// Run it:  node examples/01-request-flow/trace.js
//
// The three players are the same ones a MERN app has:
//   browser  -> asks for data      (React runs here)
//   server   -> receives the call  (Node.js + Express run here)
//   database -> keeps the data     (MongoDB runs here; we fake it with an array)
import http from 'node:http';

const database = [
  { id: 1, company: 'Acme Logistics', role: 'Dispatcher', status: 'applied' },
  { id: 2, company: 'Northwind Bank', role: 'Teller', status: 'interview' },
];

const log = (who, what) => console.log(`[${who.padEnd(8)}] ${what}`);

const server = http.createServer((req, res) => {
  log('server', `received ${req.method} ${req.url}`);
  if (req.method === 'GET' && req.url === '/api/jobs') {
    log('server', 'asking the database for all jobs');
    const jobs = database; // in a real app this is a MongoDB query
    log('database', `found ${jobs.length} documents`);
    res.setHeader('Content-Type', 'application/json');
    res.end(JSON.stringify(jobs));
    log('server', 'sent the jobs back as JSON');
    return;
  }
  res.statusCode = 404;
  res.end('Not found');
});

server.listen(0, async () => {
  const { port } = server.address();
  log('browser', `calling GET http://localhost:${port}/api/jobs`);
  const response = await fetch(`http://localhost:${port}/api/jobs`);
  const jobs = await response.json();
  log('browser', `got status ${response.status} and ${jobs.length} jobs`);
  for (const job of jobs) log('browser', `draw a card: ${job.role} at ${job.company} (${job.status})`);
  server.close();
});

// Lesson 2: check that your computer is ready.   Run:  node examples/02-setup/check-setup.js
import { execSync } from 'node:child_process';

const major = Number(process.versions.node.split('.')[0]);
const tools = [
  { name: 'Node.js', check: () => `v${process.versions.node}`, ok: () => major >= 20, help: 'Install the LTS version from nodejs.org' },
  { name: 'npm', check: () => execSync('npm -v').toString().trim(), ok: () => true, help: 'npm comes with Node.js' },
  { name: 'Git', check: () => execSync('git --version').toString().trim(), ok: () => true, help: 'Install Git from git-scm.com' },
];

let allGood = true;
for (const t of tools) {
  try {
    const version = t.check();
    const good = t.ok();
    if (!good) allGood = false;
    console.log(`${good ? 'OK     ' : 'UPGRADE'} ${t.name}: ${version}${good ? '' : '  -> ' + t.help}`);
  } catch {
    allGood = false;
    console.log(`MISSING ${t.name}  -> ${t.help}`);
  }
}
console.log(allGood ? '\nYou are ready for lesson 3.' : '\nFix the lines above, then run this again.');

// Lesson 3: the modern JavaScript used in every MERN app.   Run:  node examples/03-javascript/es6-tour.js

// const and let (never var)
const company = 'Acme Logistics';
let attempts = 1;
attempts += 1;

// template strings
console.log(`Applied to ${company}, attempt ${attempts}`);

// objects, destructuring and shorthand
const job = { id: 7, role: 'Dispatcher', salary: { min: 18000, max: 24000 }, tags: ['night shift', 'local'] };
const { role, salary: { max }, tags: [firstTag] } = job;
console.log(role, max, firstTag);

// spread: copy and change without touching the original (React state depends on this)
const updated = { ...job, status: 'interview' };
console.log(job.status, updated.status); // undefined interview
const moreTags = [...job.tags, 'full time'];
console.log(moreTags);

// arrow functions and array methods
const jobs = [
  { id: 1, role: 'Teller', status: 'applied' },
  { id: 2, role: 'Dispatcher', status: 'interview' },
  { id: 3, role: 'Driver', status: 'applied' },
];
const applied = jobs.filter((j) => j.status === 'applied');
const roles = jobs.map((j) => j.role);
const firstInterview = jobs.find((j) => j.status === 'interview');
const counts = jobs.reduce((acc, j) => ({ ...acc, [j.status]: (acc[j.status] || 0) + 1 }), {});
console.log(applied.length, roles, firstInterview.role, counts);

// optional chaining and default values
const maybe = { company: { name: 'Northwind' } };
console.log(maybe.company?.name ?? 'unknown', maybe.owner?.name ?? 'no owner');

// ES modules: export in one file, import in another (see helpers.js)
import { formatSalary } from './helpers.js';
console.log(formatSalary(job.salary));

// Lesson 4: asynchronous JavaScript.   Run:  node examples/04-async/async-tour.js
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// 1) A callback: "call me when you are done" (the old style)
setTimeout(() => console.log('callback: 100 ms passed'), 100);

// 2) A promise: a value that arrives later
const loadJob = (id) =>
  new Promise((resolve, reject) => {
    setTimeout(() => (id > 0 ? resolve({ id, role: 'Teller' }) : reject(new Error('Bad id'))), 50);
  });
loadJob(1).then((job) => console.log('promise:', job.role)).catch((err) => console.log(err.message));

// 3) async / await: the same thing, written like normal top-to-bottom code
async function main() {
  await wait(150);
  try {
    const job = await loadJob(2);
    console.log('await:', job.role);
    await loadJob(0); // this one rejects
  } catch (err) {
    console.log('caught:', err.message); // errors from await are caught with try/catch
  }

  // run things at the same time, wait for all of them
  const [a, b] = await Promise.all([loadJob(3), loadJob(4)]);
  console.log('Promise.all:', a.id, b.id);

  // fetch is built into Node 18+ and into every browser
  const server = (await import('node:http')).createServer((req, res) => res.end(JSON.stringify({ ok: true }))).listen(0);
  const res = await fetch(`http://localhost:${server.address().port}/`);
  console.log('fetch:', res.status, await res.json());
  server.close();
}
main();

// Lesson 5: HTTP and REST with only Node.js, so you can see what Express will do for you later.
// Run:  node examples/05-http-rest/rest-without-express.js   then in a second terminal:
//   curl -i http://localhost:3000/api/jobs
//   curl -i -X POST http://localhost:3000/api/jobs -H "Content-Type: application/json" -d '{"company":"Acme","role":"Clerk"}'
//   curl -i http://localhost:3000/api/jobs/1
//   curl -i -X DELETE http://localhost:3000/api/jobs/1
import http from 'node:http';

let nextId = 2;
const jobs = [{ id: 1, company: 'Northwind Bank', role: 'Teller' }];

const send = (res, status, body) => {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(body === undefined ? '' : JSON.stringify(body));
};

const readBody = (req) =>
  new Promise((resolve) => {
    let raw = '';
    req.on('data', (chunk) => (raw += chunk));
    req.on('end', () => { try { resolve(JSON.parse(raw || '{}')); } catch { resolve(null); } });
  });

http.createServer(async (req, res) => {
  const [path] = req.url.split('?');
  const match = /^\/api\/jobs\/(\d+)$/.exec(path);

  if (req.method === 'GET' && path === '/api/jobs') return send(res, 200, jobs);                       // 200 OK
  if (req.method === 'POST' && path === '/api/jobs') {
    const body = await readBody(req);
    if (!body || !body.company || !body.role) return send(res, 400, { message: 'company and role are required' }); // 400 Bad Request
    const job = { id: nextId++, company: body.company, role: body.role };
    jobs.push(job);
    return send(res, 201, job);                                                                          // 201 Created
  }
  if (match && req.method === 'GET') {
    const job = jobs.find((j) => j.id === Number(match[1]));
    return job ? send(res, 200, job) : send(res, 404, { message: 'Job not found' });                     // 404 Not Found
  }
  if (match && req.method === 'DELETE') {
    const i = jobs.findIndex((j) => j.id === Number(match[1]));
    if (i === -1) return send(res, 404, { message: 'Job not found' });
    jobs.splice(i, 1);
    return send(res, 204);                                                                               // 204 No Content
  }
  send(res, 404, { message: 'No such route' });
}).listen(3000, () => console.log('REST demo on http://localhost:3000'));

