import { HttpError } from '../utils/HttpError.js';

export const STATUSES = ['saved', 'applied', 'interview', 'offer', 'rejected'];

const text = (v) => (typeof v === 'string' ? v.trim() : '');

// Check and clean the body of a job. `partial` is true for updates, where every field is optional.
export function cleanJob(body = {}, { partial = false } = {}) {
  const problems = {};
  const out = {};

  for (const field of ['company', 'role']) {
    if (body[field] === undefined && partial) continue;
    const v = text(body[field]);
    if (!v) problems[field] = `${field} is required`;
    else if (v.length > 120) problems[field] = `${field} must be 120 characters or fewer`;
    else out[field] = v;
  }
  if (body.status !== undefined) {
    if (!STATUSES.includes(body.status)) problems.status = `status must be one of: ${STATUSES.join(', ')}`;
    else out.status = body.status;
  } else if (!partial) out.status = 'saved';

  if (Object.keys(problems).length) throw new HttpError(400, 'Please fix the highlighted fields', problems);
  return out;
}

// An error that knows which HTTP status to answer with.
export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

// Runs when no route matched.
export const notFound = (req, res) => {
  res.status(404).json({ message: `No route for ${req.method} ${req.originalUrl}` });
};

// Runs when anything throws (Express 5 also forwards errors from async functions to here).
// It has four parameters: that is how Express knows it is an error handler.
// eslint-disable-next-line no-unused-vars
export const errorHandler = (err, req, res, next) => {
  if (err.type === 'entity.parse.failed') return res.status(400).json({ message: 'The request body is not valid JSON' });
  const status = err.status || 500;
  if (status >= 500) console.error(err); // log real bugs, but do not leak details to the client
  res.status(status).json({
    message: status >= 500 ? 'Something went wrong on the server' : err.message,
    ...(err.details ? { details: err.details } : {}),
  });
};

import { HttpError } from '../utils/HttpError.js';
import { cleanJob } from '../middleware/validate.js';

let nextId = 3;
const jobs = [
  { id: 1, company: 'Northwind Bank', role: 'Teller', status: 'applied' },
  { id: 2, company: 'Acme Logistics', role: 'Dispatcher', status: 'interview' },
];

const find = (id) => {
  const job = jobs.find((j) => j.id === Number(id));
  if (!job) throw new HttpError(404, 'Job not found');
  return job;
};

export const listJobs = (req, res) => res.json(jobs);
export const getJob = (req, res) => res.json(find(req.params.id));

export const createJob = (req, res) => {
  const job = { id: nextId++, ...cleanJob(req.body) };
  jobs.push(job);
  res.status(201).json(job);
};

export const updateJob = (req, res) => {
  const job = find(req.params.id);
  Object.assign(job, cleanJob(req.body, { partial: true }));
  res.json(job);
};

export const deleteJob = (req, res) => {
  const job = find(req.params.id);
  jobs.splice(jobs.indexOf(job), 1);
  res.status(204).end();
};

// Lesson 12: validation and error handling.
import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import { logger } from './middleware/logger.js';
import { notFound, errorHandler } from './middleware/error.js';
import jobsRouter from './routes/jobs.js';

const app = express();
const port = Number(process.env.PORT) || 5000;

app.use(logger);
app.use(cors({ origin: process.env.CLIENT_ORIGIN || 'http://localhost:5173' }));
app.use(express.json({ limit: '100kb' }));

app.get('/api/health', (req, res) => res.json({ ok: true }));
app.use('/api/jobs', jobsRouter);

app.use(notFound);     // after all routes
app.use(errorHandler); // last of all

