// A tiny script that calls your running API and checks the answers.
// Start the server first (npm run dev), then in another terminal:  npm run smoke
const base = process.env.API_URL || 'http://localhost:5000/api';
let failed = 0;

const check = (name, ok, extra = '') => {
  if (!ok) failed++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${ok ? '' : '  ' + extra}`);
};
const call = async (method, path, body) => {
  const res = await fetch(base + path, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  return { status: res.status, data: text ? JSON.parse(text) : null };
};

let r = await call('GET', '/health');
check('health answers 200', r.status === 200 && r.data.ok === true);

r = await call('POST', '/jobs', { company: 'Smoke Test Ltd', role: 'Tester' });
check('create answers 201', r.status === 201, JSON.stringify(r));
const id = r.data?.id ?? r.data?._id;

r = await call('POST', '/jobs', { company: '', status: 'maybe' });
check('bad body answers 400 with details', r.status === 400 && r.data.details?.company && r.data.details?.status, JSON.stringify(r));

r = await call('GET', `/jobs/${id}`);
check('read it back', r.status === 200 && r.data.company === 'Smoke Test Ltd', JSON.stringify(r));

r = await call('PUT', `/jobs/${id}`, { status: 'interview' });
check('update changes the status', r.status === 200 && r.data.status === 'interview', JSON.stringify(r));

r = await call('DELETE', `/jobs/${id}`);
check('delete answers 204', r.status === 204, JSON.stringify(r));

r = await call('GET', `/jobs/${id}`);
check('deleted job answers 404', r.status === 404, JSON.stringify(r));

console.log(failed ? `\n${failed} check(s) failed` : '\nAll checks passed');
process.exit(failed ? 1 : 0);

// Lesson 14: MongoDB in the shell.
// Run with mongosh (comes with MongoDB):   mongosh "<your connection string>" examples/14-mongodb/queries.mongosh.js
// This uses a database called job_tracker_demo and drops it at the end, so it is safe to run.
const db = db.getSiblingDB('job_tracker_demo');

// INSERT: a collection is created the first time you write to it
db.jobs.insertMany([
  { company: 'Northwind Bank', role: 'Teller', status: 'applied', salary: { min: 20000, max: 26000 }, tags: ['bank', 'day shift'] },
  { company: 'Acme Logistics', role: 'Dispatcher', status: 'interview', salary: { min: 18000, max: 24000 }, tags: ['night shift'] },
  { company: 'Greenfield Foods', role: 'Line Supervisor', status: 'saved', tags: ['factory'] },
]);

// FIND: filter, project (choose fields), sort, limit
print('--- applied or interview');
printjson(db.jobs.find({ status: { $in: ['applied', 'interview'] } }, { _id: 0, company: 1, status: 1 }).sort({ company: 1 }).toArray());

print('--- nested field and array');
printjson(db.jobs.find({ 'salary.min': { $gte: 19000 }, tags: 'bank' }, { _id: 0, role: 1 }).toArray());

// UPDATE: $set changes fields, $push adds to an array
db.jobs.updateOne({ company: 'Greenfield Foods' }, { $set: { status: 'applied' }, $push: { tags: 'full time' } });

// AGGREGATE: group and count (this is how the stats screen will work)
print('--- jobs per status');
printjson(db.jobs.aggregate([{ $group: { _id: '$status', count: { $sum: 1 } } }, { $sort: { count: -1 } }]).toArray());

// DELETE
db.jobs.deleteOne({ company: 'Acme Logistics' });
print('--- left:', db.jobs.countDocuments());

db.dropDatabase();

import mongoose from 'mongoose';

export async function connectDB(uri = process.env.MONGODB_URI) {
  if (!uri) throw new Error('MONGODB_URI is missing. Copy .env.example to .env and set it.');
  mongoose.connection.on('disconnected', () => console.warn('MongoDB disconnected'));
  // serverSelectionTimeoutMS: fail in 8 seconds with a clear error instead of hanging for 30
  await mongoose.connect(uri, { serverSelectionTimeoutMS: 8000 });
  console.log(`MongoDB connected: ${mongoose.connection.name}`);
}

// Lesson 15: connect to MongoDB with Mongoose before we start listening.
import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import mongoose from 'mongoose';
import { connectDB } from './config/db.js';
import { logger } from './middleware/logger.js';
import { notFound, errorHandler } from './middleware/error.js';
import jobsRouter from './routes/jobs.js';

const app = express();
const port = Number(process.env.PORT) || 5000;

app.use(logger);
app.use(cors({ origin: process.env.CLIENT_ORIGIN || 'http://localhost:5173' }));
app.use(express.json({ limit: '100kb' }));

// readyState 1 means connected
app.get('/api/health', (req, res) => res.json({ ok: true, db: mongoose.connection.readyState === 1 ? 'connected' : 'not connected' }));
app.use('/api/jobs', jobsRouter);

app.use(notFound);
app.use(errorHandler);

try {
  await connectDB();
  app.listen(port, () => console.log(`API listening on http://localhost:${port}`));
} catch (err) {
  console.error('Could not start:', err.message);
  process.exit(1);
}

import mongoose from 'mongoose';

export const STATUSES = ['saved', 'applied', 'interview', 'offer', 'rejected'];

// A schema describes the shape of a document and the rules it must follow.
const jobSchema = new mongoose.Schema(
  {
