// Lesson 36: accept one resume file per request, safely.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import multer from 'multer';

const here = path.dirname(fileURLToPath(import.meta.url));
export const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(here, '..', 'uploads');
export const MAX_BYTES = 2 * 1024 * 1024; // 2 MB
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const ALLOWED = { '.pdf': 'application/pdf', '.doc': 'application/msword', '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' };

const storage = multer.diskStorage({
  destination: UPLOAD_DIR,
  // Never use the name the client sent as a path. A random name cannot clash and cannot escape the folder.
  filename: (req, file, cb) => cb(null, crypto.randomBytes(16).toString('hex') + path.extname(file.originalname).toLowerCase()),
});

export const upload = multer({
  storage,
  limits: { fileSize: MAX_BYTES, files: 1 },
  fileFilter: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    if (!ALLOWED[ext]) return cb(Object.assign(new Error('Only PDF, DOC or DOCX files are accepted'), { status: 400 }));
    cb(null, true);
  },
});

// The browser can lie about a file's type, so also look at the first bytes ("magic numbers") of what was saved.
export function looksLikeAllowedFile(filePath) {
  const fd = fs.openSync(filePath, 'r');
  const head = Buffer.alloc(8);
  fs.readSync(fd, head, 0, 8, 0);
  fs.closeSync(fd);
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.pdf') return head.subarray(0, 5).toString() === '%PDF-';
  if (ext === '.docx') return head[0] === 0x50 && head[1] === 0x4b; // "PK": a zip container
  if (ext === '.doc') return head[0] === 0xd0 && head[1] === 0xcf; // old Office container
  return false;
}

export const removeFile = (storedName) => {
  if (!/^[a-f0-9]{32}\.(pdf|doc|docx)$/.test(storedName || '')) return; // only ever delete names we made
  fs.rm(path.join(UPLOAD_DIR, storedName), { force: true }, () => {});
};

import mongoose from 'mongoose';

export const STATUSES = ['saved', 'applied', 'interview', 'offer', 'rejected'];

// The attached resume. We keep the file on disk and only its details in MongoDB.
const resumeSchema = new mongoose.Schema(
  {
    originalName: { type: String, required: true }, // what the person called it (shown to them)
    storedName: { type: String, required: true },   // random name on disk (never shown, never trusted from the client)
    size: { type: Number, required: true },
    uploadedAt: { type: Date, default: Date.now },
  },
  { _id: false },
);

const jobSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    company: { type: String, required: [true, 'company is required'], trim: true, maxlength: 120 },
    role: { type: String, required: [true, 'role is required'], trim: true, maxlength: 120 },
    location: { type: String, trim: true, maxlength: 120, default: '' },
    status: { type: String, enum: { values: STATUSES, message: 'status must be one of: ' + STATUSES.join(', ') }, default: 'saved' },
    salaryNote: { type: String, trim: true, maxlength: 120, default: '' },
    notes: { type: String, trim: true, maxlength: 2000, default: '' },
    appliedOn: { type: Date },
    resume: { type: resumeSchema, default: undefined },
  },
  { timestamps: true },
);

jobSchema.index({ user: 1, createdAt: -1 });
jobSchema.index({ user: 1, status: 1, createdAt: -1 });

jobSchema.set('toJSON', {
  virtuals: true,
  versionKey: false,
  transform: (doc, ret) => {
    delete ret._id;
    delete ret.user;
    if (ret.resume) ret.resume = { name: ret.resume.originalName, size: ret.resume.size, uploadedAt: ret.resume.uploadedAt }; // hide storedName
    return ret;
  },
});

export default mongoose.model('Job', jobSchema);

import path from 'node:path';
import Job from '../models/Job.js';
import { HttpError } from '../utils/HttpError.js';
import { UPLOAD_DIR, looksLikeAllowedFile, removeFile } from '../middleware/upload.js';

const ownJob = async (req) => {
  const job = await Job.findOne({ _id: req.params.id, user: req.user._id });
  if (!job) throw new HttpError(404, 'Job not found');
  return job;
};

export const uploadResume = async (req, res) => {
  if (!req.file) throw new HttpError(400, 'Choose a file to upload (form field "resume")');
  const saved = path.join(UPLOAD_DIR, req.file.filename);
  try {
    const job = await ownJob(req);
    if (!looksLikeAllowedFile(saved)) throw new HttpError(400, 'That file does not look like a real PDF or Word document');
    removeFile(job.resume?.storedName); // replace the old file
    job.resume = { originalName: path.basename(req.file.originalname).slice(0, 120), storedName: req.file.filename, size: req.file.size };
    await job.save();
    res.status(201).json(job);
  } catch (err) {
    removeFile(req.file.filename); // do not leave orphan files behind
    throw err;
  }
};

export const downloadResume = async (req, res) => {
  const job = await ownJob(req);
  if (!job.resume) throw new HttpError(404, 'No resume attached');
  // download() sets Content-Disposition so the browser saves it with the original name
  res.download(path.join(UPLOAD_DIR, job.resume.storedName), job.resume.originalName);
};

export const deleteResume = async (req, res) => {
  const job = await ownJob(req);
  if (job.resume) {
    removeFile(job.resume.storedName);
    job.resume = undefined;
    await job.save();
  }
  res.status(204).end();
};

