const TOKEN_KEY = 'jt_token';

export const getToken = () => localStorage.getItem(TOKEN_KEY);
export const setToken = (t) => (t ? localStorage.setItem(TOKEN_KEY, t) : localStorage.removeItem(TOKEN_KEY));

export class ApiError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

const authHeader = () => (getToken() ? { Authorization: `Bearer ${getToken()}` } : {});

async function fail(res, path) {
  const data = await res.json().catch(() => null);
  if (res.status === 401 && getToken() && !path.startsWith('/auth/login')) window.dispatchEvent(new Event('jt:unauthorized'));
  throw new ApiError(res.status, data?.message || `Request failed (${res.status})`, data?.details);
}

export async function api(path, { method = 'GET', body, signal } = {}) {
  const headers = { ...authHeader() };
  let payload;
  if (body instanceof FormData) {
    payload = body; // the browser adds the multipart Content-Type (with its boundary) itself. Do not set it.
  } else if (body !== undefined) {
    headers['Content-Type'] = 'application/json';
    payload = JSON.stringify(body);
  }
  const res = await fetch(`/api${path}`, { method, headers, signal, body: payload });
  if (res.status === 204) return null;
  if (!res.ok) await fail(res, path);
  return res.json();
}

// A plain <a href> cannot send our Authorization header, so fetch the file and save it from memory.
export async function downloadFile(path, filename) {
  const res = await fetch(`/api${path}`, { headers: authHeader() });
  if (!res.ok) await fail(res, path);
  const url = URL.createObjectURL(await res.blob());
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.append(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

import { useState } from 'react';
import { api, downloadFile } from '../api.js';

const MAX = 2 * 1024 * 1024;

// Attach, download or remove the resume you sent for one job.
export default function ResumeFile({ job, onChange }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  async function pick(e) {
    const file = e.target.files[0];
    e.target.value = ''; // so choosing the same file again still fires onChange
    if (!file) return;
    if (file.size > MAX) { setError('That file is larger than 2 MB.'); return; } // check early to save the upload
    setBusy(true);
    setError('');
    try {
      const body = new FormData();
      body.append('resume', file); // the field name must match upload.single('resume') on the server
      onChange(await api(`/jobs/${job.id}/resume`, { method: 'POST', body }));
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  async function remove() {
    setBusy(true);
    try {
      await api(`/jobs/${job.id}/resume`, { method: 'DELETE' });
      onChange({ ...job, resume: undefined });
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="card" aria-labelledby="resume-heading">
      <h2 id="resume-heading">Resume you sent</h2>
      {job.resume ? (
        <p>
          <button className="link-btn" onClick={() => downloadFile(`/jobs/${job.id}/resume`, job.resume.name).catch((e) => setError(e.message))}>{job.resume.name}</button>
          {' '}<span className="muted">({Math.max(1, Math.round(job.resume.size / 1024))} KB)</span>{' · '}
          <button className="link-btn danger" onClick={remove} disabled={busy}>Remove</button>
        </p>
      ) : <p className="muted">Nothing attached yet.</p>}
      <div className="field">
        <label htmlFor="resume-file">{job.resume ? 'Replace with another file' : 'Attach a PDF or Word file (2 MB at most)'}</label>
        <input id="resume-file" type="file" accept=".pdf,.doc,.docx" onChange={pick} disabled={busy} />
      </div>
      {error && <p className="error" role="alert">{error}</p>}
    </section>
  );
}

import { useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { api } from '../api.js';
import { useAuth } from '../context/AuthContext.jsx';
import JobForm from '../components/JobForm.jsx';
import ResumeFile from '../components/ResumeFile.jsx';

export default function JobDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { ready } = useAuth();
  const [job, setJob] = useState(null);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (!ready) return undefined;
    const controller = new AbortController();
    api(`/jobs/${id}`, { signal: controller.signal })
      .then(setJob)
      .catch((err) => err.name !== 'AbortError' && setError(err.status === 404 ? 'That job was not found.' : err.message));
    return () => controller.abort();
  }, [id, ready]);

  async function save(values) {
    const updated = await api(`/jobs/${id}`, { method: 'PUT', body: values });
    setJob(updated);
    setSaved(true);
  }

  async function remove() {
    if (!window.confirm('Delete this job?')) return;
    await api(`/jobs/${id}`, { method: 'DELETE' });
    navigate('/'); // go back to the list
  }

  if (error) return <p className="error" role="alert">{error} <Link to="/">Back to my jobs</Link></p>;
  if (!job) return <p className="muted">Loading…</p>;
  return (
    <>
      <h1>{job.role} at {job.company}</h1>
      {/* key={job.updatedAt} makes React build a fresh form when the saved job changes */}
      <JobForm key={job.updatedAt} initial={job} onSubmit={save} submitLabel="Save changes" resetAfter={false} />
      {saved && <p role="status" className="ok">Saved.</p>}
      <ResumeFile job={job} onChange={setJob} />
      <p className="muted">
        <Link to="/">← Back to my jobs</Link>{' · '}
        <button className="link-btn danger" onClick={remove}>Delete this job</button>
      </p>
    </>
  );
}

// Lesson 37: logs a person reads in development, and one JSON object per line in production
// (easy for tools such as pm2, journald, Loki or any log search to read and filter).
const production = process.env.NODE_ENV === 'production';

const write = (level, message, extra = {}) => {
  if (production) {
    console[level === 'error' ? 'error' : 'log'](JSON.stringify({ time: new Date().toISOString(), level, message, ...extra }));
  } else {
    console[level === 'error' ? 'error' : 'log'](`[${level}] ${message}`, Object.keys(extra).length ? extra : '');
  }
};

export const log = {
  info: (m, x) => write('info', m, x),
  warn: (m, x) => write('warn', m, x),
  error: (m, x) => write('error', m, x),
};

import { log } from '../utils/logger.js';

// One line per request, written when the answer has been sent. We log the path WITHOUT the query string
// and never the body or headers: they can contain passwords and tokens.
export function logger(req, res, next) {
  const started = Date.now();
  res.on('finish', () => {
    log.info(`${req.method} ${req.path} ${res.statusCode}`, { ms: Date.now() - started, status: res.statusCode, ip: req.ip });
  });
  next();
}

import 'dotenv/config';
import mongoose from 'mongoose';
import { checkEnv } from './config/env.js';
import { connectDB } from './config/db.js';
import { log } from './utils/logger.js';
import { app } from './app.js';

const port = Number(process.env.PORT) || 5000;
let server;

// Graceful shutdown: when pm2 or the host says "stop", finish the requests in progress, close the database, then exit.
async function shutdown(signal) {
  log.info(`${signal} received, shutting down`);
  const force = setTimeout(() => { log.error('Forced exit after 10 seconds'); process.exit(1); }, 10_000);
  force.unref();
  try {
    await new Promise((resolve) => (server ? server.close(resolve) : resolve()));
    await mongoose.disconnect();
    process.exit(0);
  } catch (err) {
    log.error('Error while shutting down', { error: err.message });
    process.exit(1);
  }
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
// A promise nobody caught is a bug. Log it; pm2 restarts the process if we exit.
process.on('unhandledRejection', (reason) => { log.error('Unhandled rejection', { reason: String(reason) }); process.exit(1); });

try {
  checkEnv();
  await connectDB();
  server = app.listen(port, () => log.info(`API listening on port ${port}`, { env: process.env.NODE_ENV || 'development' }));
} catch (err) {
  log.error(`Could not start: ${err.message}`);
  process.exit(1);
}

import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import compression from 'compression';
import mongoose from 'mongoose';
import { logger } from './middleware/logger.js';
import { authLimiter, rejectOperators } from './middleware/security.js';
import { notFound, errorHandler } from './middleware/error.js';
import authRouter from './routes/auth.js';
import jobsRouter from './routes/jobs.js';

export const app = express();

if (process.env.TRUST_PROXY) app.set('trust proxy', Number(process.env.TRUST_PROXY) || process.env.TRUST_PROXY);

app.use(helmet());
app.use(compression()); // gzip JSON and text answers: much smaller on slow mobile connections
if (process.env.NODE_ENV !== 'test') app.use(logger);
app.use(cors({ origin: (process.env.CLIENT_ORIGIN || 'http://localhost:5173').split(',') }));
app.use(express.json({ limit: '100kb' }));
app.use(rejectOperators);

// Used by load balancers, uptime monitors and pm2. 503 tells them "do not send traffic here yet".
app.get('/api/health', (req, res) => {
  const db = mongoose.connection.readyState === 1;
  res.status(db ? 200 : 503).json({ ok: db, db: db ? 'connected' : 'not connected', uptimeSeconds: Math.round(process.uptime()) });
});
app.use('/api/auth', authLimiter, authRouter);
app.use('/api/jobs', jobsRouter);

app.use(notFound);
app.use(errorHandler);

import mongoose from 'mongoose';
import { log } from '../utils/logger.js';

export async function connectDB(uri = process.env.MONGODB_URI) {
  if (!uri) throw new Error('MONGODB_URI is missing. Copy .env.example to .env and set it.');
  mongoose.connection.on('disconnected', () => log.warn('MongoDB disconnected'));
  mongoose.connection.on('reconnected', () => log.info('MongoDB reconnected'));
  await mongoose.connect(uri, {
    serverSelectionTimeoutMS: 8000,
    // In production, build indexes on purpose with `npm run indexes`, not on every start of a busy server.
    autoIndex: process.env.NODE_ENV !== 'production',
  });
  log.info(`MongoDB connected: ${mongoose.connection.name}`);
}

// Creates (and removes outdated) indexes to match the models.   Run after a deploy that changed an index:  npm run indexes
import 'dotenv/config';
import mongoose from 'mongoose';
import { connectDB } from '../config/db.js';
import Job from '../models/Job.js';
import User from '../models/User.js';

await connectDB();
for (const model of [User, Job]) {
  const dropped = await model.syncIndexes();
  console.log(`${model.modelName}: indexes in sync${dropped.length ? ` (removed ${dropped.join(', ')})` : ''}`);
}
await mongoose.disconnect();

// Lesson 38: in production, the same Express app also serves the built React app.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import compression from 'compression';
import mongoose from 'mongoose';
import { logger } from './middleware/logger.js';
import { authLimiter, rejectOperators } from './middleware/security.js';
import { notFound, errorHandler } from './middleware/error.js';
import authRouter from './routes/auth.js';
import jobsRouter from './routes/jobs.js';

export const app = express();

if (process.env.TRUST_PROXY) app.set('trust proxy', Number(process.env.TRUST_PROXY) || process.env.TRUST_PROXY);

app.use(helmet());
app.use(compression());
if (process.env.NODE_ENV !== 'test') app.use(logger);
app.use(cors({ origin: (process.env.CLIENT_ORIGIN || 'http://localhost:5173').split(',') }));
app.use(express.json({ limit: '100kb' }));
app.use(rejectOperators);

app.get('/api/health', (req, res) => {
  const db = mongoose.connection.readyState === 1;
  res.status(db ? 200 : 503).json({ ok: db, db: db ? 'connected' : 'not connected', uptimeSeconds: Math.round(process.uptime()) });
});
app.use('/api/auth', authLimiter, authRouter);
app.use('/api/jobs', jobsRouter);
app.use('/api', notFound); // an unknown /api path is a JSON 404, never the React page

// ---- the React build (client/dist), if it exists ----
const dist = process.env.CLIENT_DIST || path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'client', 'dist');
if (fs.existsSync(path.join(dist, 'index.html'))) {
  // Files in /assets have a hash in their name, so they can be cached for a year. index.html must never be cached,
  // or visitors would keep an old page that points at files you have deleted.
  app.use(express.static(dist, {
    index: false,
    setHeaders: (res, file) => res.setHeader('Cache-Control', file.includes(`${path.sep}assets${path.sep}`) ? 'public, max-age=31536000, immutable' : 'no-cache'),
  }));
  // React Router handles paths like /jobs/123 in the browser, so any other GET gets index.html.
  app.get(/^\/(?!api\/).*/, (req, res) => {
    res.setHeader('Cache-Control', 'no-cache');
    res.sendFile(path.join(dist, 'index.html'));
  });
}

app.use(notFound);
app.use(errorHandler);

