// pm2 keeps the server running, restarts it if it crashes, and starts it again after a reboot.
//   pm2 start deploy/ecosystem.config.cjs --env production
//   pm2 save && pm2 startup
module.exports = {
  apps: [
    {
      name: 'job-tracker',
      cwd: './server',
      script: 'index.js',
      instances: 1,            // one is plenty for a small app. Several need the "cluster" mode and no in-memory state.
      max_memory_restart: '300M',
      kill_timeout: 12000,     // a little longer than our 10 second graceful shutdown
      env: { NODE_ENV: 'development' },
      env_production: { NODE_ENV: 'production', TRUST_PROXY: '1' },
    },
  ],
};

# nginx in front of Node: handles HTTPS, compression of static files and large uploads.
# Save as /etc/nginx/sites-available/jobtracker.example.com.conf, link it into sites-enabled, then:
#   sudo nginx -t && sudo systemctl reload nginx
#   sudo certbot --nginx -d jobtracker.example.com        (adds the HTTPS part and renewals)
server {
    listen 80;
    server_name jobtracker.example.com;

    client_max_body_size 3m;   # our uploads are 2 MB at most; nginx's default of 1 MB would answer 413 first

    location / {
        proxy_pass http://127.0.0.1:5000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;   # Express reads this because TRUST_PROXY=1
    }
}
